SET statement_timeout = 0;

-- Drop the specific index if it exists and is invalid
\set drop_invalid 0
SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM pg_index i
    JOIN pg_class c ON c.oid = i.indexrelid
    WHERE i.indrelid = 'orders'::regclass
      AND NOT i.indisvalid
      AND c.relname = 'orders_external_ref_unique_idx'
) THEN '1' ELSE '0' END AS drop_invalid \gset

\if :drop_invalid = 1
DROP INDEX CONCURRENTLY orders_external_ref_unique_idx;
\endif

-- Check if a unique constraint on external_ref already exists
\set constraint_exists 0
SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM pg_constraint c
    JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)
    WHERE c.conrelid = 'orders'::regclass
      AND c.contype = 'u'
      AND a.attname = 'external_ref'
) THEN '1' ELSE '0' END AS constraint_exists \gset

\if :constraint_exists = 1
\echo Unique constraint on external_ref already exists. Exiting.
\quit
\endif

-- Create the unique index if it doesn't already exist as valid
\set create_index 0
SELECT CASE WHEN EXISTS (
    SELECT 1
    FROM pg_index i
    JOIN pg_class c ON c.oid = i.indexrelid
    WHERE i.indrelid = 'orders'::regclass
      AND i.indisunique
      AND i.indisvalid
      AND c.relname = 'orders_external_ref_unique_idx'
) THEN '0' ELSE '1' END AS create_index \gset

\if :create_index = 1
CREATE UNIQUE INDEX CONCURRENTLY orders_external_ref_unique_idx ON orders (external_ref);
\endif

-- Add the constraint, waiting for a gap in analytics transactions
DO $$
DECLARE
    deadline timestamptz := now() + interval '30 seconds';
    analytics_active boolean;
    constraint_exists boolean;
BEGIN
    -- Double-check constraint existence (in case another process added it)
    SELECT EXISTS (
        SELECT 1 FROM pg_constraint
        WHERE conrelid = 'orders'::regclass
          AND contype = 'u'
          AND conname = 'orders_external_ref_unique'
    ) INTO constraint_exists;
    IF constraint_exists THEN
        RAISE NOTICE 'Constraint already exists, skipping';
        RETURN;
    END IF;

    LOOP
        -- Check for active analytics transactions (including idle in transaction)
        SELECT EXISTS (
            SELECT 1 FROM pg_stat_activity
            WHERE usename = 'analytics'
              AND state IN ('active', 'idle in transaction')
              AND backend_type = 'client backend'
              AND pid <> pg_backend_pid()
        ) INTO analytics_active;

        IF NOT analytics_active THEN
            -- Attempt to add constraint with a short lock timeout
            BEGIN
                SET LOCAL lock_timeout = '200ms';
                EXECUTE 'ALTER TABLE orders ADD CONSTRAINT orders_external_ref_unique UNIQUE USING INDEX orders_external_ref_unique_idx';
                EXIT;
            EXCEPTION WHEN lock_not_available THEN
                RAISE NOTICE 'Lock timeout while adding constraint, retrying...';
            END;
        END IF;

        IF now() > deadline THEN
            RAISE EXCEPTION 'Timeout waiting for analytics transaction gap';
        END IF;

        PERFORM pg_sleep(0.1);
    END LOOP;
END $$;

